def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    if mode and mode not in ("READ", "WRITE"):
        raise ValueError("Transaction mode must be "READ" or "WRITE", got {!r}".format(mode))
    if bookmarks and not isinstance(bookmarks, (list, tuple)):
        raise TypeError("Bookmarks must be a list or tuple of values, got {!r}.".format(bookmarks))
    if metadata and not isinstance(metadata, dict):
        raise TypeError("Metadata must be a dict, got {!r}".format(metadata))
    if timeout and not isinstance(timeout, (int, float)):
        raise TypeError("Timeout must be a number, got {!r}".format(timeout))
    if db and not isinstance(db, str):
        raise TypeError("Database name must be a string, got {!r}".format(db))
    if imp_user and not isinstance(imp_user, str):
        raise TypeError("Impersonated user must be a string, got {!r}".format(imp_user))
    if dehydration_hooks and not isinstance(dehydration_hooks, dict):
        raise TypeError("Dehydration hooks must be a dict, got {!r}".format(dehydration_hooks))
    if hydration_hooks and not isinstance(hydration_hooks, dict):
        raise TypeError("Hydration hooks must be a dict, got {!r}".format(hydration_hooks))
    if not dehydration_hooks:
        dehydration_hooks = {}
    if not hydration_hooks:
        hydration_hooks = {}
    packet = BeginMessage()
    if mode:
        packet["mode"] = mode
    if bookmarks:
        packet["bookmarks"] = list(bookmarks)
    if metadata:
        packet["metadata"] = dict(metadata)
    if timeout:
        packet["timeout"] = float(timeout)
    if db:
        packet["db"] = db
    if imp_user:
        packet["imp_user"] = imp_user
    packet["dehydration_hooks"] = dehydration_hooks
    packet["hydration_hooks"] = hydration_hooks
    self.append(packet)
    return Response(self, **handlers)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer.
    If the number is halfway between two integers,
    it is rounded to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n - int(n) == 0.5:
        if int(n) % 2 == 0:
            return int(n)
        else:
            return int(n) + 1
    return int(n)

