def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = []
    for part in s.split("."):
        try:
            parts.append(int(part))
        except ValueError:
            parts.append(0)
    return tuple(parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split(".")
    return tuple([int(p) for p in parts])

