def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if platform.system() == "Windows":
        # Fix for issue #8557: Python on Windows will not honor shebangs
        # when a script's name does not end with .py extension.
        for path in iter(cmd):
            if path != 'python' and os.path.splitext(path)[1] != '.py':
                path = path.replace('python', 'pythonw')
            else:
                path = path.strip('/"')
        return tuple(path)
    else:
        return cmd

