from functools import wraps
from unstdlib.standard.collections_ import LRUCache

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError('expected maxsize to be an integer or None')

    if ttl is not None and not isinstance(ttl, int):
        raise TypeError('expected ttl to be an integer or None')

    if timer is not None and not callable(timer):
        raise TypeError('expected timer to be a callable or None')

    def decorator(func):
        if not callable(func):
            raise TypeError('expected a callable')

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get the current time from the timer function.
            now = timer()

            # Create a new LRU cache if necessary.
            if not hasattr(wrapper, 'cache'):
                wrapper.cache = LRUCache(maxsize)

            # Try to get the result from the cache.
            try:
                key = (args, frozenset(kwargs.items()) if typed else kwargs)
                value, timestamp = wrapper.cache[key]
                if ttl is None or now - timestamp < ttl:
                    return value
            except KeyError:
                pass

            # Call the function and save the result in the cache.
            value = func(*args, **kwargs)
            wrapper.cache[key] = (value, now)
            return value

        return wrapper

    return decorator
