def extostr(cls, e, max_level=30, max_path_level=5):
    tb = traceback.format_exc()
    path = traceback.extract_tb(tb)
    path = path[:max_path_level]
    msg = f"{e.__class__.__name__}: {e}"
    msg += "\nCall stack:\n"
    for i, (filename, lineno, name, line) in enumerate(path):
        msg += f"  File '{filename}', line {lineno}, in {name}\n"
        if line:
            msg += f"    {line.strip()}\n"
        if i >= max_level - 1:
            msg += "    ...\n"
    return msg

