def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    `spec.manifest` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Iterate over the manifests in the application
    for manifest in app.manifest:
        # Check if a custom observer schema has been specified for the manifest
        if manifest.metadata.name in app.observer_schemas:
            continue

        # Generate a default observer schema for the manifest
        observer_schema = {}

        # Iterate over the fields in the manifest
        for field, value in manifest.items():
            # Check if the field is a Kubernetes resource
            if isinstance(value, kubernetes.client.V1ObjectMeta):
                # Check if the resource has a status
                if hasattr(value, 'status'):
                    # Add the status field to the observer schema
                    observer_schema[field] = {}
                    observer_schema[field]['type'] = 'object'
                    observer_schema[field]['properties'] = {}

                    # Iterate over the status fields
                    for status_field, status_value in value.status.items():
                        # Check if the status field is a list
                        if isinstance(status_value, list):
                            # Add the list field to the observer schema
                            status_list_schema = []
                            status_list_schema['type'] = 'array'
                            status_list_schema['items'] = {}

                            # Iterate over the items in the list
                            for item in status_value:
                                # Check if the item is a Kubernetes resource
                                if isinstance(item, kubernetes.client.V1ObjectMeta):
                                    # Add the item to the list schema
                                    status_list_schema['items']['type'] = 'object'
                                    status_list_schema['items']['properties'] = {}
                        elif isinstance(status_value, kubernetes.client.V1ObjectMeta):
                            # Add the Kubernetes resource to the observer schema
                            observer_schema[field]['properties'][status_field] = {}
                            observer_schema[field]['properties'][status_field]['type'] = 'object'
                            observer_schema[field]['properties'][status_field]['properties'] = {}

        # Add the default observer schema to the application
        app.observer_schemas[manifest.metadata.name] = observer_schema
