def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        try:
            type_value = inventory['type']
        except KeyError:
            pass
        else:
            if isinstance(type_value, str) and type_value.strip() == '':
                raise SchemaFormatError("The 'type' value must be a non-empty string.")
            elif not isinstance(type_value, str):
                raise SchemaFormatError("The 'type' value must be a string.")
            else:
                if type_value.lower() == 'aws_')

    # Check for the presence of required attributes
    required_keys = ['spec_version', 'inventory']
    if self.spec_version in (0.7, 0.8, 0.9, 1.0):
        required_keys.append('description')
    else:
        required_keys.append('description')

    missing_keys = set(required_keys) - set(inventory)
    if missing_keys:
        raise SchemaFormatError(f"The following required keys are missing from the inventory: {', '.join(missing_keys)}")

    # Check that all attributes are valid
    for key, value in inventory.items():
        if key in required_keys:
            if not isinstance(value, str):
                raise SchemaFormatError(f"The value for the '{key}' key must be a string")
            if not value.strip():
                raise SchemaFormatError(f"The value for the '{key}' key cannot be a blank string.")
        elif key == 'inventory':
            if not isinstance(value, dict):
                raise SchemaFormatError(f"The value for the '{key}' key must be a dictionary.")
            for item_name, item_data in value.items():
                if not isinstance(item_name, str):
                    raise SchemaFormatError(f"The key for the item data must be a string")
                if not isinstance(item_data, dict):
                    raise SchemaFormatError(f"The value for the '{item_name}' key must be a dictionary.")
                for attr_name, attr_value in item_data.items():
                    if not isinstance(attr_value, str):
                        raise SchemaFormatError(f"The value for the '{attr_name}' attribute must be a string.")
                    if not attr_value.strip():
                        raise SchemaFormatError(f"The value for the '{attr_name}' attribute cannot be a blank string.")
                    if attr_name in ('add', 'remove'):
                        if not isinstance(attr_value, list):
                            raise SchemaFormatError(f"The value for the '{attr_name}' attribute must be a list.")
                        for item in attr_value:
                            if not isinstance(item, InventoryItem):
                                raise SchemaFormatError(f"The value for the '{attr_name}' attribute must be a list of InventoryItem objects.")

    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Check if the inventory is a valid buffer
    if not isinstance(inventory, bytes):
        raise TypeError("Inventory must be a bytes-like object")

    # Check if the inventory length is valid
    if len(inventory) < 2:
        raise ValueError("Inventory must have a length of at least 2")

    # Check if the first byte is 0x04
    if ord(inventory[0]) != 0x04:
        raise ValueError("Inventory must start with 0x04")

    # Check if the second byte is a valid type flag
    type_flag = ord(inventory[1])
    if type_flag not in [0x01, 0x02, 0x03]:
        raise ValueError("Inventory must have a valid type flag")

    # Extract the version, if requested
    if extract_spec_version:
        try:
            version = ord(inventory[2:3])
        except IndexError:
            raise ValueError("Inventory must have a version byte")
        if version not in [1, 2, 3, 4]:
            raise ValueError("Inventory must have a valid version number")
        self.spec_version = version

    # Check if the inventory has a valid checksum
    checksum = inventory[-4:]
    if checksum != sha256(inventory[:-4]).digest()[:4]:
        raise ValueError("Inventory has invalid checksum")

    return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get('type', None)
        if type_value is not None:
            version = None
            try:
                version = int(type_value)
            except ValueError:
                pass
    if version is not None:
        return self.validate_historical(inventory, version)
    return self.validate_current(inventory)

def validate_historical(self, inventory, version):
    """Validate a given inventory against a specific spec version.

    Returns the validated inventory if it passes, or raises a ValidationError
    if it fails.
