    if version not in self.historical_specs:
        raise ValidationError(f"Unknown spec version: {version}")
    spec = self.historical_specs[version]
    return self.validate_current(inventory, spec)

def validate_current(self, inventory, spec=None):
    """Validate a given inventory against the current spec.

    Returns the validated inventory if it passes, or raises a ValidationError
    if it fails.
    """
    # Get the current spec if not specified
    if spec is None:
        spec = self.current_spec

    # Validate the inventory against the spec
    return self.validator.validate(inventory, spec)

