def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check metadata
    if self.metadata != prior.metadata:
        raise ValueError("Mismatching metadata")

    # Check sizes
    if self.size != prior.size:
        raise ValueError("Mismatching sizes")

    # Check versions
    if self.version < prior.version:
        raise ValueError("A prior version cannot be lower than the current version")

    # Check that prior is a subset of self
    if not all(elem in self.inventory for elem in prior.inventory):
        raise ValueError("Prior inventory is not a subset of the current inventory")

    # Check that all items in prior have smaller or equal quantities than in self
    for item in prior.inventory:
        if self.inventory[item] < prior.inventory[item]:
            raise ValueError("Prior inventory has larger quantity than current inventory for item: {}".format(item))

