def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = []
    xml_files = []
    tmp_dict = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                xml_files.append(os.path.join(root, f))
    for xml_file in xml_files:
        package = {}
        tree = ElementTree.parse(xml_file)
        root = tree.getroot()
        basename = os.path.basename(xml_file)
        package['filename'] = basename
        package['version'] = root.find('version')
        package['release_status'] = root.find('release_status')
        packages.append(package)
    for package in packages:
        basename = package['filename']
        if basename in tmp_dict:
            tmp_dict[basename].append(package)
        else:
            tmp_dict[basename] = [package]
    return tmp_dict

def _eval_file(prefix, filename, file_folder):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    packages: Dict[str, Any] = {}

    if prefix == "asset":
        packages[filename] = {"type": "asset", "file": file_folder + filename}
    elif prefix == "rendition":
        rendition_file = filename[filename.find("rendition") + 9:]
        packages[rendition_file] = {
            "type": "rendition",
            "file": file_folder + rendition_file,
        }
    else:
        packages[filename] = {"type": "unknown", "file": file_folder + filename}

    return packages

def _eval_file(prefix, file_path):
    file_type = 'asset' if prefix == 'asset' else 'rendition'
    packages[file_path] = {
        'type': file_type,
