def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return None

    version_parts = version.split('.')
    if len(version_parts) < 3:
        return None

    release_part = version_parts[0]
    major_part = version_parts[1]
    minor_part = version_parts[2]

    if release_part.startswith('0'):
        release_part = str(int(release_part) + 1).zfill(2)
    else:
        release_part = str(int(release_part) + 1)

    if major_part.startswith('0'):
        major_part = str(int(major_part) + 1).zfill(2)
    else:
        major_part = str(int(major_part) + 1)

    if minor_part.startswith('0'):
        minor_part = str(int(minor_part) + 1).zfill(2)
    else:
        minor_part = str(int(minor_part) + 1)

    return f"{release_part}.{major_part}.{minor_part}"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    # Check that each version directory has an inventory file
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise ValueError(f'Missing inventory file for version {version_dir}')

    # Check that each version has an inventory that is up to date
    for i, version_dir in enumerate(version_dirs):
        inventory_path = os.path.join(version_dir, 'inventory.json')
        with open(inventory_path, 'r') as f:
            inventory = json.load(f)
        root_inventory = os.path.join(os.path.abspath('.'), 'inventory.json')
        with open(root_inventory, 'r') as f:
            root_inventory = json.load(f)
        for key, value in inventory.items():
            if key not in root_inventory or value != root_inventory[key]:
                raise ValueError(f'Inventory for version {version_dir} is not up to date')

    # Keep a record of any content digests different from those in the root inventory
    self.content_digests = {}
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        with open(inventory_path, 'r') as f:
            inventory = json.load(f)
        for key, value in inventory.items():
            if key not in self.content_digests or value != self.content_digests[key]:
                self.content_digests[key] = value

    # Check that each content file has an inventory that is up to date
    for content_file, digest in self.content_digests.items():
        file_path = os.path.join(os.path.abspath('.'), content_file)
        if not os.path.exists(file_path):
            raise ValueError(f'Missing content file {content_file}')
        with open(file_path, 'rb') as f:
            content_bytes = f.read()
            content_digest = hashlib.sha256(content_bytes).hexdigest()
        if content_digest != digest:
            raise ValueError(f'Inventory for content file {content_file} is not up to date')

