def validate_version_tree(self):
    """Validate the version tree."""
    # Check if the version tree is empty
    if not self.version_tree:
        raise ValueError("Version tree is empty.")

    # Check if the root version is present
    if self.version not in self.version_tree:
        raise ValueError(f"Root version {self.version} is not present in the version tree.")

    # Check if the version tree is valid
    for version in self.version_tree.keys():
        if version not in self.version_tree[version]:
            raise ValueError(f"Version {version} is not present in the version tree.")

    # Check if there are any cycles in the version tree
    for version in self.version_tree.keys():
        visited = set()
        to_visit = [version]
        while to_visit:
            current = to_visit.pop()
            if current in visited:
                raise ValueError(f"Cycle detected in version tree at version {current}.")
            visited.add(current)
            for child in self.version_tree[current]:
                if child not in visited:
                    to_visit.append(child)
