    """Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    from click.inspect import get_info
    from click.pleasantries import add_completion
    from click.tildepaths import expand_tilde_paths
    from click.types import BashCompletionCommand

    def get_options(func):
        info = get_info(func)
        options = []
        for param in info.get('params', []):
            if param.param_type_name == 'option':
                options.append(param.opts[0])
        return options

    def get_arguments(func):
        info = get_info(func)
        arguments = []
        for param in info.get('params', []):
            if param.param_type_name == 'argument':
                arguments.append(param.name)
        return arguments

    def get_commands(cls):
        commands = set()
        for attr in dir(cls):
            if attr.startswith('_'):
                continue
            value = getattr(cls, attr)
            if callable(value) and getattr(value, '__click_command__', False):
                commands.add(attr)
        return list(commands)

    def generate_completion(context, command):
        info = get_info(command)
        options = get_options(command)
        arguments = get_arguments(command)
        subcommands = get_commands(command)

        yield '_options={}'.format(' '.join(options))

        if arguments:
            yield '_arguments={}'.format(' '.join(arguments))

        if subcommands:
            yield '_subcommands={}'.format(' '.join(subcommands))

        yield from filter(bool, (
            info.get('help'),
            info.get('usage_options'),
            info.get('usage_options_single'),
        ))

    bash_completion = BashCompletionCommand('borgmatic', generate_completion)
    add_completion(bash_completion)

    return bash_completion

