def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

    Examples:
        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    size = size.upper()
    multiplier = 1
    if size.endswith("KB"):
        multiplier = 1000
    elif size.endswith("MB"):
        multiplier = 1000000
    elif size.endswith("GB"):
        multiplier = 1000000000
    elif size.endswith("TB"):
        multiplier = 1000000000000
    elif size.endswith("PB"):
        multiplier = 1000000000000000
    elif size.endswith("EB"):
        multiplier = 1000000000000000000
    elif size.endswith("ZB"):
        multiplier = 1000000000000000000000
    elif size.endswith("YB"):
        multiplier = 1000000000000000000000000
    try:
        return int(float(size[:-2]) * multiplier)
    except ValueError:
        raise ValueError("Invalid file size: %s" % size)

