    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if len(digits) > padding:
        raise ValueError("Number too large to fit in the given alphabet and padding")
    else:
        return "".join(digits)

