def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if filename is None:
        raise ValueError("Filename cannot be None")

    if not isinstance(archive_path, str):
        raise TypeError("Archive path must be a string")

    if not os.path.exists(archive_path):
        raise FileNotFoundError("Archive path does not exist")

    if not isinstance(tmp_path, (PosixPath, str)):
        raise TypeError("tmp_path must be a PosixPath or a string")

    if not os.path.isdir(tmp_path):
        raise NotADirectoryError("tmp_path is not a directory")

    archive_name, archive_ext = os.path.splitext(archive_path)
    if archive_ext not in (".zip", ".tar", ".tar.gz", ".tar.bz2", ".tbz", ".tbz2"):
        raise ValueError("Unsupported archive format")

    if not os.path.isfile(os.path.join(archive_path, filename)):
        raise FileNotFoundError("File not found in archive")

    if os.path.isdir(os.path.join(tmp_path, filename)):
        raise FileExistsError("File already exists in tmp_path")

    file_repo_url = os.path.join(tmp_path, filename)

    if archive_ext == ".zip":
        with zipfile.ZipFile(archive_path, "r") as zip_ref:
            zip_ref.extractall(tmp_path)
    else:
        with tarfile.open(archive_path, "r:" + archive_ext.lstrip(".")) as tar_ref:
            tar_ref.extractall(tmp_path)

    return file_repo_url
