        num, unit = match.groups()
        unit = unit.lower()
        if unit in freq_map:
            num = int(num)
            if unit == "weeks":
                timedelta_args = {"days": num * 7}
            else:
                timedelta_args = {freq_map[unit]: num}
            return datetime.timedelta(**timedelta_args)
        else:
            raise ValueError("Invalid frequency unit: %s" % unit)
