def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid('{} does not provide interface {}'.format(candidate, iface))

    for name, method in iface.names():
        if name not in candidate:
            raise Invalid('{} does not define {} method'.format(candidate, name))
        if not zope.interface.Compatibility.consider(method, candidate[name]):
            raise Invalid('{} does not implement {} with compatible signature'.format(candidate, name))

    for name, attr in iface.names():
        if name not in candidate:
            raise Invalid('{} does not define {} attribute'.format(candidate, name))
        if not zope.interface.Compatibility.consider(attr, candidate[name]):
            raise Invalid('{} does not implement {} with compatible type'.format(candidate, name))

    return True

