def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        reader = JsonReader(document)
        jsondata = reader.read()
        webfinger = WebFinger(jsondata)
        return webfinger.to_dict()
    except Exception as e:
        logger.warning("Failed to parse Diaspora webfinger in JSON format, trying XRD format")
        try:
            reader = XRDReader(document)
            xrddata = reader.read()
            webfinger = WebFinger(xrddata)
            return webfinger.to_dict()
        except Exception as e:
            logger.error("Failed to parse Diaspora webfinger in XRD format")
            raise e

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        document_dict = json.loads(document)
    except json.JSONDecodeError:
        xrd_root = ElementTree.fromstring(document)
        xrd_subject = xrd_root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject")
        xrd_links = xrd_root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
        document_dict = {
            "subject": xrd_subject.text if xrd_subject is not None else None,
            "links": [
                {
                    "rel": link.attrib.get("rel"),
                    "type": link.attrib.get("type"),
                    "href": link.attrib["href"],
                }
                for link in xrd_links
            ],
        }
    return document_dict

