    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for spec in options_spec:
        if 'required_when' in spec:
            condition = spec['required_when']
            if isinstance(condition, str):
                if condition in args:
                    required_args.append(spec['name'])
            elif isinstance(condition, collections.abc.Sequence):
                if any(arg in args for arg in condition):
                    required_args.append(spec['name'])
            elif isinstance(condition, collections.abc.Mapping):
                if any(args.get(arg) == val for arg, val in condition.items()):
                    required_args.append(spec['name'])
            else:
                raise ValueError(
                    "the condition %s is not supported" % condition)

    return required_args

