    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Get the received arguments
    min_ = args.get('min_', None)
    max_ = args.get('max_', None)

    # Check if the value of arguments is between minimum and maximum values
    for arg in args:
        if min_ is not None and max_ is not None:
            if arg < min_ or arg > max_:
                raise ValueError("The value of argument {} must be between {} and {}".format(arg, min_, max_))
        elif min_ is None and max_ is not None:
            if arg > max_:
                raise ValueError("The value of argument {} must be less than or equal to {}".format(arg, max_))
        elif min_ is not None and max_ is None:
            if arg < min_:
                raise ValueError("The value of argument {} must be greater than or equal to {}".format(arg, min_))
        else:
            raise ValueError("Either minimum or maximum value must be provided")

